    const image = {
      title: "Misty valley at sunrise",
      collection: "Travel inspiration",
      size: "4.8 MB",
      dimensions: "2400 x 1650",
      dateAdded: "May 6, 2026"
    };

    const Header = () => `
      <header>
        <a class="brand" href="#" aria-label="Lumina library home">
          <span class="brand-mark" aria-hidden="true">L</span>
          <span>Lumina Library</span>
        </a>
        <a class="library-link" href="#">Back to library</a>
      </header>
    `;

    const ImagePreview = ({ title }) => `
      <section class="image-card" aria-labelledby="image-title">
        <div class="image-wrap" role="img" aria-label="${title}"></div>
        <div class="image-caption">
          <div>
            <h2 id="image-title">${title}</h2>
            <p>High-resolution image preview selected from your saved library.</p>
          </div>
          <button class="button-secondary" type="button">Download</button>
        </div>
      </section>
    `;

    const DetailsPanel = ({ collection, size, dimensions, dateAdded }) => `
      <aside class="details-card" aria-labelledby="details-title">
        <div>
          <p class="eyebrow">Image preview</p>
          <h1 id="main-heading">Review your image</h1>
          <ul class="meta-list" aria-labelledby="details-title">
            <li><span id="details-title">Collection</span><strong>${collection}</strong></li>
            <li><span>File size</span><strong>${size}</strong></li>
            <li><span>Dimensions</span><strong>${dimensions}</strong></li>
            <li><span>Date added</span><strong>${dateAdded}</strong></li>
          </ul>
        </div>
        <div>
          <div class="button-row">
            <button class="trigger" type="button" aria-haspopup="dialog">
              Delete image
            </button>
            <button class="button-primary" type="button">Edit details</button>
          </div>
          <p class="status-message" aria-live="polite"></p>
        </div>
      </aside>
    `;

    const DeleteDialog = ({ title }) => `
      <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
        <div class="dialog-panel">
          <div class="dialog-icon" aria-hidden="true">!</div>
          <h2 id="dialog-title">Delete image?</h2>
          <p id="dialog-description">
            This will remove "${title}" from your library. This action cannot be undone.
          </p>
          <div class="dialog-actions">
            <button class="button-secondary" type="button" data-dialog-close>Cancel</button>
            <button class="button-danger" type="button" data-confirm-delete>Delete image</button>
          </div>
        </div>
      </dialog>
    `;

    const App = ({ image }) => `
      <div class="app-shell">
        ${Header()}
        <main id="main-content" tabindex="-1" aria-labelledby="main-heading">
          <div class="preview-layout">
            ${ImagePreview(image)}
            ${DetailsPanel(image)}
          </div>
        </main>
      </div>
      ${DeleteDialog(image)}
    `;

    const root = document.querySelector("#root");
    root.innerHTML = App({ image });

    const dialog = document.querySelector("#delete-dialog");
    const trigger = document.querySelector(".trigger");
    const closeButton = document.querySelector("[data-dialog-close]");
    const confirmButton = document.querySelector("[data-confirm-delete]");
    const statusMessage = document.querySelector(".status-message");

    trigger.addEventListener("click", () => {
      dialog.showModal();
      closeButton.focus();
    });

    closeButton.addEventListener("click", () => {
      dialog.close("cancel");
    });

    confirmButton.addEventListener("click", () => {
      dialog.close("delete");
      statusMessage.textContent = "Image deleted from your library.";
      trigger.disabled = true;
      trigger.textContent = "Image deleted";
    });

    dialog.addEventListener("click", (event) => {
      if (event.target === dialog) {
        dialog.close("backdrop");
      }
    });

    dialog.addEventListener("close", () => {
      if (dialog.returnValue !== "delete") {
        trigger.focus();
      }
    });
  </script>
