      position: absolute;
      top: 1rem;
      left: 1rem;
      z-index: 10;
      transform: translateY(-150%);
      border-radius: 999px;
      background: var(--text);
      color: #ffffff;
      padding: 0.75rem 1rem;
      text-decoration: none;
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #93c5fd;
      outline-offset: 3px;
    }

    .app-shell {
      width: min(1120px, 100%);
      margin: 0 auto;
      padding: 2rem;
    }

    header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 2rem;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      color: var(--text);
      font-weight: 800;
      letter-spacing: -0.03em;
      text-decoration: none;
    }

    .brand-mark {
      display: grid;
      width: 2.5rem;
      height: 2.5rem;
      place-items: center;
      border-radius: 14px;
      background: var(--primary);
      color: #ffffff;
      font-weight: 900;
    }

    .library-link {
      border: 1px solid var(--border);
      border-radius: 999px;
      background: #ffffffcc;
      color: var(--text);
      padding: 0.7rem 1rem;
      font-weight: 700;
      text-decoration: none;
    }

    main {
      outline: none;
    }

    .preview-layout {
      display: grid;
      grid-template-columns: minmax(0, 1.35fr) minmax(18rem, 0.65fr);
      gap: 1.5rem;
      align-items: stretch;
    }

    .image-card,
    .details-card {
      border: 1px solid #ffffff;
      border-radius: var(--radius-lg);
      background: #fffffff2;
      box-shadow: var(--shadow);
    }

    .image-card {
      overflow: hidden;
    }

    .image-wrap {
      aspect-ratio: 16 / 11;
      background:
        linear-gradient(135deg, #17255466, #312e8166),
        url("https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80") center / cover;
      min-height: 20rem;
    }

    .image-caption {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1.25rem;
    }

    .image-caption p {
      margin: 0.2rem 0 0;
      color: var(--muted);
      line-height: 1.5;
    }

    .details-card {
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 1.5rem;
    }

    .eyebrow {
      margin: 0 0 0.7rem;
      color: var(--primary);
      font-size: 0.82rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1,
    h2,
    h3,
    p {
      overflow-wrap: anywhere;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.15rem, 7vw, 4.75rem);
      line-height: 0.95;
      letter-spacing: -0.07em;
    }

    h2 {
      margin: 0;
      font-size: 1.2rem;
      letter-spacing: -0.03em;
    }

    .meta-list {
      display: grid;
      gap: 0.9rem;
      margin: 1.8rem 0;
      padding: 0;
      list-style: none;
    }

    .meta-list li {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      border-bottom: 1px solid var(--surface-soft);
      padding-bottom: 0.9rem;
      color: var(--muted);
    }

    .meta-list strong {
      color: var(--text);
      font-weight: 800;
      text-align: right;
    }

    .button-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
    }

    button {
      min-height: 2.75rem;
      border: 0;
      border-radius: 999px;
      padding: 0.78rem 1rem;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
    }

    button:focus-visible,
    a:focus-visible {
      outline: 3px solid var(--primary);
      outline-offset: 3px;
    }

    .button-secondary {
      border: 1px solid var(--border);
      background: var(--surface);
      color: var(--text);
    }

    .button-primary {
      background: var(--primary);
      color: #ffffff;
    }

    .button-primary:hover {
      background: var(--primary-strong);
    }

    .button-danger {
      background: var(--danger);
      color: #ffffff;
    }

    .button-danger:hover {
      background: var(--danger-strong);
    }

    .trigger {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.45rem;
      background: var(--danger-soft);
      color: var(--danger-strong);
    }

    .trigger:hover {
      background: #fecaca;
    }

    .status-message {
      min-height: 1.5rem;
      margin: 1rem 0 0;
      color: var(--danger-strong);
      font-weight: 700;
    }

    dialog {
      width: min(92vw, 31rem);
      border: 0;
      border-radius: 24px;
      padding: 0;
      color: var(--text);
      background: var(--surface);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: #0f172acc;
      backdrop-filter: blur(8px);
    }

    .dialog-panel {
      padding: 1.5rem;
    }

    .dialog-icon {
      display: grid;
      width: 3rem;
      height: 3rem;
      margin-bottom: 1rem;
      place-items: center;
      border-radius: 16px;
      background: var(--danger-soft);
      color: var(--danger-strong);
      font-size: 1.5rem;
      font-weight: 900;
    }

    .dialog-panel h2 {
      font-size: 1.45rem;
    }

    .dialog-panel p {
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap-reverse;
      justify-content: flex-end;
      gap: 0.75rem;
      margin-top: 1.25rem;
    }

    @media (max-width: 760px) {
      .app-shell {
        padding: 1rem;
      }

      header,
      .image-caption {
        align-items: flex-start;
        flex-direction: column;
      }

      .preview-layout {
        grid-template-columns: 1fr;
      }

      .image-wrap {
        min-height: 16rem;
      }

      .details-card,
      .dialog-panel {
        padding: 1.15rem;
      }

      .button-row,
      .dialog-actions,
      .button-row button,
      .dialog-actions button {
        width: 100%;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
      }
    }

    @media (forced-colors: active) {
      body,
      .image-card,
      .details-card,
      dialog,
      .button-secondary,
      .trigger {
        background: Canvas;
        color: CanvasText;
      }

      .brand-mark,
      .button-primary,
      .button-danger {
        border: 1px solid ButtonBorder;
        background: ButtonFace;
        color: ButtonText;
      }

      .dialog-icon {
        border: 1px solid ButtonBorder;
        background: Canvas;
        color: CanvasText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="root"></div>

  <script>
    const image = {
      title: "Misty valley at sunrise",
      collection: "Travel inspiration",
      size: "4.8 MB",
      dimensions: "2400 x 1650",
      dateAdded: "May 6, 2026"
    };

    const Header = () => `
      <header>
        <a class="brand" href="#" aria-label="Lumina library home">
          <span class="brand-mark" aria-hidden="true">L</span>
          <span>Lumina Library</span>
        </a>
        <a class="library-link" href="#">Back to library</a>
      </header>
    `;

    const ImagePreview = ({ title }) => `
      <section class="image-card" aria-labelledby="image-title">
        <div class="image-wrap" role="img" aria-label="${title}"></div>
        <div class="image-caption">
          <div>
            <h2 id="image-title">${title}</h2>
            <p>High-resolution image preview selected from your saved library.</p>
          </div>
          <button class="button-secondary" type="button">Download</button>
        </div>
      </section>
    `;

    const DetailsPanel = ({ collection, size, dimensions, dateAdded }) => `
      <aside class="details-card" aria-labelledby="details-title">
        <div>
          <p class="eyebrow">Image preview</p>
          <h1 id="main-heading">Review your image</h1>
          <ul class="meta-list" aria-labelledby="details-title">
            <li><span id="details-title">Collection</span><strong>${collection}</strong></li>
            <li><span>File size</span><strong>${size}</strong></li>
            <li><span>Dimensions</span><strong>${dimensions}</strong></li>
            <li><span>Date added</span><strong>${dateAdded}</strong></li>
          </ul>
        </div>
        <div>
          <div class="button-row">
            <button class="trigger" type="button" aria-haspopup="dialog">
              Delete image
            </button>
            <button class="button-primary" type="button">Edit details</button>
          </div>
          <p class="status-message" aria-live="polite"></p>
        </div>
      </aside>
    `;

    const DeleteDialog = ({ title }) => `
      <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
        <div class="dialog-panel">
          <div class="dialog-icon" aria-hidden="true">!</div>
          <h2 id="dialog-title">Delete image?</h2>
          <p id="dialog-description">
            This will remove "${title}" from your library. This action cannot be undone.
          </p>
          <div class="dialog-actions">
            <button class="button-secondary" type="button" data-dialog-close>Cancel</button>
            <button class="button-danger" type="button" data-confirm-delete>Delete image</button>
          </div>
        </div>
      </dialog>
    `;

    const App = ({ image }) => `
      <div class="app-shell">
        ${Header()}
        <main id="main-content" tabindex="-1" aria-labelledby="main-heading">
          <div class="preview-layout">
            ${ImagePreview(image)}
            ${DetailsPanel(image)}
          </div>
        </main>
      </div>
      ${DeleteDialog(image)}
    `;

    const root = document.querySelector("#root");
    root.innerHTML = App({ image });

    const dialog = document.querySelector("#delete-dialog");
    const trigger = document.querySelector(".trigger");
    const closeButton = document.querySelector("[data-dialog-close]");
    const confirmButton = document.querySelector("[data-confirm-delete]");
    const statusMessage = document.querySelector(".status-message");

    trigger.addEventListener("click", () => {
      dialog.showModal();
      closeButton.focus();
    });

    closeButton.addEventListener("click", () => {
      dialog.close("cancel");
    });

    confirmButton.addEventListener("click", () => {
      dialog.close("delete");
      statusMessage.textContent = "Image deleted from your library.";
      trigger.disabled = true;
      trigger.textContent = "Image deleted";
    });

    dialog.addEventListener("click", (event) => {
      if (event.target === dialog) {
        dialog.close("backdrop");
      }
    });

    dialog.addEventListener("close", () => {
      if (dialog.returnValue !== "delete") {
        trigger.focus();
      }
    });
  </script>
</body>
</html>
